#!/usr/bin/env python3
"""Convert benchmarks/trustgraph/airkg_schema.ttl (OWL, rdflib-generated by
schema_to_owl.py) into TrustGraph's config-service ontology JSON, the format
consumed by trustgraph.extract.kg.ontology.ontology_loader (fork @ v2.8.15).

Target shape (from OntologyClass.from_dict / OntologyProperty.from_dict):
{
  "metadata": {...},
  "classes":            { <id>: {uri, type, rdfs:label, rdfs:comment, ...} },
  "objectProperties":   { <id>: {uri, type, rdfs:label, rdfs:comment,
                                 rdfs:domain, rdfs:range} },
  "datatypeProperties": { ... }
}
Ids are the local names; rdfs:domain / rdfs:range values must be CLASS IDS
(the loader validates them against `classes` keys); datatype ranges are kept
as CURIEs (xsd:string / xsd:boolean; not validated by the loader).

KNOWN LOSSY MAPPINGS (their format cannot express these — recorded, not
silently dropped; printed to stderr and returned in the fidelity report):
  - owl:unionOf domains/ranges: their format holds a single class id.
    Policy: emit NO domain/range for that slot (a wrong single class would
    be more misleading than none) and count the loss.
  - owl:SymmetricProperty: no field; lost.
  - rdfs:seeAlso external alignments: no field; lost.

Usage:
  python3 owl_to_tg_ontology.py [--ttl airkg_schema.ttl] [--id airkg] > airkg_ontology.json
"""
import argparse
import json
import sys
from pathlib import Path

from rdflib import Graph, RDF, RDFS, OWL, URIRef

HERE = Path(__file__).resolve().parent


def local(uri):
    s = str(uri)
    return s.rsplit("#", 1)[-1] if "#" in s else s.rsplit("/", 1)[-1]


def curie_xsd(uri):
    s = str(uri)
    if s.startswith("http://www.w3.org/2001/XMLSchema#"):
        return "xsd:" + s.rsplit("#", 1)[-1]
    return s


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--ttl", default=str(HERE / "airkg_schema.ttl"))
    ap.add_argument("--id", default="airkg")
    args = ap.parse_args()

    g = Graph()
    g.parse(args.ttl, format="turtle")

    losses = {"union_domain": [], "union_range": [],
              "symmetric": [], "seealso": []}

    def labels_of(s):
        out = [{"value": str(o), "lang": "en"} for o in g.objects(s, RDFS.label)]
        return out or [{"value": local(s).replace("_", " "), "lang": "en"}]

    def comment_of(s):
        for o in g.objects(s, RDFS.comment):
            return str(o)
        return None

    def single_class_or_none(prop, term, kind):
        """Resolve rdfs:domain/range to a single class id, or None for
        owl:unionOf (recorded as a loss)."""
        val = next(iter(g.objects(prop, term)), None)
        if val is None:
            return None
        if isinstance(val, URIRef):
            return local(val)
        # blank node: owl:unionOf list
        losses[kind].append(local(prop))
        return None

    classes = {}
    for s in sorted(g.subjects(RDF.type, OWL.Class)):
        if not isinstance(s, URIRef):
            continue  # union class bnodes
        entry = {"uri": str(s), "type": "owl:Class", "rdfs:label": labels_of(s)}
        c = comment_of(s)
        if c:
            entry["rdfs:comment"] = c
        classes[local(s)] = entry

    def build_props(rdf_type, type_str, datatype=False):
        props = {}
        for s in sorted(g.subjects(RDF.type, rdf_type)):
            entry = {"uri": str(s), "type": type_str, "rdfs:label": labels_of(s)}
            c = comment_of(s)
            if c:
                entry["rdfs:comment"] = c
            dom = single_class_or_none(s, RDFS.domain, "union_domain")
            if dom:
                entry["rdfs:domain"] = dom
            if datatype:
                rng = next(iter(g.objects(s, RDFS.range)), None)
                if rng is not None:
                    entry["rdfs:range"] = curie_xsd(rng)
            else:
                rng = single_class_or_none(s, RDFS.range, "union_range")
                if rng:
                    entry["rdfs:range"] = rng
            if (s, RDF.type, OWL.SymmetricProperty) in g:
                losses["symmetric"].append(local(s))
            for o in g.objects(s, RDFS.seeAlso):
                losses["seealso"].append(local(s))
            props[local(s)] = entry
        return props

    object_props = build_props(OWL.ObjectProperty, "owl:ObjectProperty")
    datatype_props = build_props(OWL.DatatypeProperty, "owl:DatatypeProperty",
                                 datatype=True)

    ont_uri = next(iter(g.subjects(RDF.type, OWL.Ontology)), None)
    version = next(iter(g.objects(ont_uri, OWL.versionInfo)), None) if ont_uri else None

    doc = {
        "metadata": {
            "id": args.id,
            "name": "AI-readiness KG schema",
            "description": ("Schema-derived ontology from kg/schema.yaml "
                            f"v{version} via schema_to_owl.py + "
                            "owl_to_tg_ontology.py"),
            "uri": str(ont_uri) if ont_uri else "",
            "version": str(version) if version else "",
        },
        "classes": classes,
        "objectProperties": object_props,
        "datatypeProperties": datatype_props,
    }

    counts = {"classes": len(classes), "objectProperties": len(object_props),
              "datatypeProperties": len(datatype_props)}
    print(json.dumps(doc, indent=2, sort_keys=True))
    print(json.dumps({"counts": counts, "losses": losses}, indent=2,
                     sort_keys=True), file=sys.stderr)


if __name__ == "__main__":
    main()
